UPDATE servers SET details_json=json_set(CASE WHEN json_valid(details_json) THEN details_json ELSE '{}' END, '$.summary', 'Official reference filesystem MCP server for reading, searching and modifying files within explicitly allowed directories. Supports read-only mode and directory access controls; review paths before granting access.', '$.tools', json('[{"name":"read_text_file","description":"Read UTF-8 text from an allowed file."},{"name":"read_multiple_files","description":"Read several allowed files in one call."},{"name":"list_directory","description":"List entries in an allowed directory."},{"name":"search_files","description":"Search for files under allowed directories."},{"name":"write_file","description":"Create or overwrite a file; requires write access."},{"name":"edit_file","description":"Modify an existing file; requires write access."},{"name":"list_allowed_directories","description":"List directories the server is permitted to access."}]'), '$.security', json('["Grant access only to specific directories; never use the entire home directory unless necessary.","Use --read-only when editing is not needed; consider --confine-roots for older Roots-capable clients.","Write and edit tools can change or overwrite files."]'), '$.contentSource', 'https://github.com/modelcontextprotocol/servers/blob/main/src/filesystem/README.md', '$.contentReviewedAt', '2026-11-22', '$.contentVerification', 'maintainer-documentation-reviewed; runtime-not-tested') WHERE id='filesystem-mcp';

UPDATE servers SET details_json=json_set(CASE WHEN json_valid(details_json) THEN details_json ELSE '{}' END, '$.summary', 'Official reference MCP server providing a sequential_thinking tool for structured, revisable problem-solving. Supports revising earlier thoughts, branching approaches, and changing the estimated number of steps.', '$.tools', json('[{"name":"sequential_thinking","description":"Record a reasoning step, revise previous steps, or branch into alternative approaches."}]'), '$.security', json('["Thought logging can include sensitive prompts; consider DISABLE_THOUGHT_LOGGING=true when appropriate.","This tool helps organize reasoning; it does not independently verify the correctness of conclusions."]'), '$.contentSource', 'https://github.com/modelcontextprotocol/servers/blob/main/src/sequentialthinking/README.md', '$.contentReviewedAt', '2026-11-22', '$.contentVerification', 'maintainer-documentation-reviewed; runtime-not-tested') WHERE id='sequential-thinking-mcp';

UPDATE servers SET details_json=json_set(CASE WHEN json_valid(details_json) THEN details_json ELSE '{}' END, '$.summary', 'Official reference knowledge-graph memory MCP server. Stores entities, typed relationships, and observations for later retrieval and updates.', '$.tools', json('[{"name":"create_entities","description":"Create entities with names, types, and observations."},{"name":"create_relations","description":"Link existing entities with typed relationships."},{"name":"add_observations","description":"Add facts to existing entities."},{"name":"search_nodes","description":"Find entities by name, type, or observation."},{"name":"open_nodes","description":"Retrieve selected entities and their relationships."},{"name":"read_graph","description":"Read the knowledge graph."},{"name":"delete_entities","description":"Remove entities and their associated relations."}]'), '$.security', json('["Stored observations may contain personal or confidential information; restrict access to the backing storage.","Deletion tools can remove entities, observations and relationships.","Consider MEMORY_MAX_ENTITIES, MEMORY_MAX_RELATIONS and MEMORY_MAX_FILE_BYTES limits."]'), '$.contentSource', 'https://github.com/modelcontextprotocol/servers/blob/main/src/memory/README.md', '$.contentReviewedAt', '2026-11-22', '$.contentVerification', 'maintainer-documentation-reviewed; runtime-not-tested') WHERE id='memory-mcp';

UPDATE servers SET details_json=json_set(CASE WHEN json_valid(details_json) THEN details_json ELSE '{}' END, '$.summary', 'Official reference Python MCP server that retrieves web pages and converts HTML to Markdown. Provides a fetch tool with pagination, raw-output and timeout options.', '$.tools', json('[{"name":"fetch","description":"Fetch a URL and return readable Markdown or raw content, with optional length and offset controls."}]'), '$.security', json('["Fetch accesses external sites and can disclose URLs or requested content to those hosts.","The current default blocks private and loopback IP addresses; do not enable --allow-private-ips without understanding the risk.","Review proxy configuration and robots.txt behavior before autonomous crawling."]'), '$.contentSource', 'https://github.com/modelcontextprotocol/servers/blob/main/src/fetch/README.md', '$.contentReviewedAt', '2026-11-22', '$.contentVerification', 'maintainer-documentation-reviewed; runtime-not-tested') WHERE id='fetch-mcp';

UPDATE servers SET details_json=json_set(CASE WHEN json_valid(details_json) THEN details_json ELSE '{}' END, '$.summary', 'Grafana-maintained MCP integration for dashboards, metrics, logs, traces, alerts and incidents. Tool availability depends on enabled categories, Grafana deployment and account permissions.', '$.tools', json('[{"name":"search_dashboards","description":"Search dashboards by title and other supported filters."},{"name":"get_dashboard_summary","description":"Retrieve a compact dashboard overview."},{"name":"get_dashboard_property","description":"Read selected dashboard properties using JSONPath."},{"name":"query_prometheus","description":"Execute PromQL queries against permitted Prometheus datasources."},{"name":"list_datasources","description":"List available Grafana datasources."},{"name":"get_datasource","description":"Retrieve details for a datasource."},{"name":"get_dashboard_by_uid","description":"Retrieve a dashboard by UID; can return large JSON."}]'), '$.security', json('["Use least-privilege Grafana service-account permissions; avoid broad editor access for read-only tasks.","Metrics, logs and traces can expose operational or sensitive information.","Some tools can modify dashboards or alerting configuration; consider --disable-write and review enabled tool categories."]'), '$.contentSource', 'https://github.com/grafana/mcp-grafana/blob/main/README.md', '$.contentReviewedAt', '2026-11-22', '$.contentVerification', 'maintainer-documentation-reviewed; runtime-not-tested') WHERE id='grafana-mcp';
